def countdown(start, log=None):
    if log is not None:
        log.append("start")
    while start > 0:
        yield start
        start -= 1
    if log is not None:
        log.append("end")


def states(gen):
    return inspect.getgeneratorstate(gen)


def consume_all(gen, log=None):
    values = list(gen)
    return values, states(gen)


