from pathlib import Path


def walk_files(root, base=None):
    base = root if base is None else base
    with os.scandir(root) as entries:
        ordered = sorted(entries, key=lambda entry: entry.name)
    for entry in ordered:
        if entry.is_dir():
            yield from walk_files(entry.path, base)
        else:
            yield Path(os.path.relpath(entry.path, base)).as_posix()


def count_files(root):
    return sum(1 for _ in walk_files(root))


def first_file(root):
    stream = walk_files(root)
    try:
        return next(stream)
    except StopIteration:
        return None
    finally:
        stream.close()


class RecursiveWalkTest(unittest.TestCase):
    def setUp(self):
        self.root = tempfile.mkdtemp()
        os.makedirs(os.path.join(self.root, "a", "b"))
        for name in ("b.txt", os.path.join("a", "one.txt"), os.path.join("a", "b", "two.txt")):
            with open(os.path.join(self.root, name), "w", encoding="utf-8") as handle:
                handle.write("x")

    def tearDown(self):
        shutil.rmtree(self.root, ignore_errors=True)

    def test_depth_first_order(self):
        self.assertEqual(list(walk_files(self.root)), ["a/b/two.txt", "a/one.txt", "b.txt"])

    def test_is_lazy_generator(self):
        stream = walk_files(self.root)
        self.assertTrue(inspect.isgenerator(stream))
        self.assertEqual(next(stream), "a/b/two.txt")
        stream.close()

    def test_count_files(self):
        self.assertEqual(count_files(self.root), 3)
        self.assertEqual(sorted(os.listdir(self.root)), ["a", "b.txt"])

    def test_first_file(self):
        self.assertEqual(first_file(self.root), "a/b/two.txt")

    def test_empty_tree(self):
        empty = tempfile.mkdtemp()
        try:
            self.assertEqual(list(walk_files(empty)), [])
            self.assertEqual(count_files(empty), 0)
            self.assertIsNone(first_file(empty))
