def group_sorted(items, key):
    return {group_key: list(group) for group_key, group in itertools.groupby(sorted(items, key=key), key=key)}


def grouping_side_effect(build):
    grouped = build()
    first_key, first_group = next(grouped)
    first_items = list(first_group)
    rest_keys = [group_key for group_key, _ in grouped]
    return first_key, first_items, rest_keys


def collect_groups(grouped):
    return [list(group) for _, group in grouped]


