        self.assertEqual(group_sorted([3, 1, 2, 1], lambda x: x), {1: [1, 1], 2: [2], 3: [3]})

    def test_groups_are_independent_lists(self):
        grouped = group_sorted([3, 1, 2, 1], lambda x: x)
        grouped[1].append(99)
        self.assertEqual(grouped[1], [1, 1, 99])
        self.assertEqual(grouped[2], [2])

    def test_empty_input(self):
        self.assertEqual(runs([], lambda x: x), [])
        self.assertEqual(group_sorted([], lambda x: x), {})

    def test_consuming_first_group_loses_nothing(self):
        def build():
            return itertools.groupby([1, 1, 2, 3, 3], key=lambda x: x)

        first_key, first_items, rest_keys = grouping_side_effect(build)
        self.assertEqual(first_key, 1)
        self.assertEqual(first_items, [1, 1])
        self.assertEqual(rest_keys, [2, 3])
        self.assertEqual(len(first_items) + len(rest_keys), 4)

    def test_consumed_groups_cover_every_input_element(self):
        def build():
            return itertools.groupby([1, 1, 2, 3, 3], key=lambda x: x)

        first_key, first_items, rest_keys = grouping_side_effect(build)
        collected = collect_groups(itertools.groupby([1, 1, 2, 3, 3], key=lambda x: x))
        self.assertEqual(collected, [[1, 1], [2], [3, 3]])
        eaten = list(first_items)
        for values in collected[1:]:
            eaten.extend(values)
        self.assertEqual(eaten, [1, 1, 2, 3, 3])
        self.assertEqual(first_key, 1)
        self.assertEqual(rest_keys, [2, 3])


