class FileRecord:
    def __init__(self, path, size, mtime):
        self.path = path
        self.size = size
        self.mtime = mtime


def make_records():
    return [
        FileRecord("a.py", 10, 3),
        FileRecord("b.log", 400, 9),
        FileRecord("c.py", 100, 7),
        FileRecord("d.py", 250, 2),
        FileRecord("e.log", 900, 8),
        FileRecord("f.py", 800, 5),
    ]


def has_suffix(*suffixes):
    return lambda record: record.path.endswith(suffixes)


def at_least(limit):
    return lambda record: record.size >= limit


def modified_before(cutoff):
    return lambda record: record.mtime < cutoff


def build_pipeline(records, predicates):
    return (record for record in records if all(p(record) for p in predicates))


def run(records, predicates):
    return [record.path for record in build_pipeline(records, predicates)]


def count_predicated_records(total, minimum, taken):
    calls = 0

    def predicate(record):
        nonlocal calls
        calls += 1
        return record.size >= minimum

    records = [FileRecord(f"f{i:03d}.py", i, i) for i in range(total)]
    pipeline = build_pipeline(records, [predicate])
    produced = 0
    for record in pipeline:
        produced += 1
        if produced == taken:
            break
    return calls


class FilterPipelineTest(unittest.TestCase):
    def setUp(self):
        self.records = make_records()

    def test_pipeline_is_an_iterator(self):
        pipeline = build_pipeline(self.records, [has_suffix(".py")])
        self.assertEqual(type(pipeline).__name__, "generator")
        self.assertFalse(hasattr(pipeline, "__len__"))
        with self.assertRaises(TypeError):
            pipeline[0]
        self.assertEqual(list(pipeline), [self.records[0], self.records[2], self.records[3], self.records[5]])

    def test_predicates_combine_with_and(self):
        paths = run(self.records, [has_suffix(".py"), at_least(100), modified_before(8)])
        self.assertEqual(paths, ["c.py", "d.py", "f.py"])

    def test_predicates_stop_early(self):
        calls = count_predicated_records(600, 580, 3)
