import unittest
from itertools import islice


def build(index, built):
    built.append(index)
    return [index, index * index]


def lazy_load(total, minimum):
    built = []
    for index in range(total):
        record = build(index, built)
        if record[1] >= minimum:
            yield record[0], len(built)


def load_all(total, minimum, built=None):
    built = [] if built is None else built
    records = [build(index, built) for index in range(total)]
    return [record[0] for record in records if record[1] >= minimum]


def first_result(stream):
    return next(iter(stream))


def only_built(total, minimum, count):
    values = list(islice(lazy_load(total, minimum), count))
    return values, values[-1][1]


class LazyObservationTest(unittest.TestCase):
    def test_lazy_first_result_is_cheap(self):
        value, built = first_result(lazy_load(6000, 100))
        self.assertEqual(value, 10)
        self.assertLess(built, 6000)

    def test_eager_first_result_pays_for_all(self):
        built = []
        self.assertEqual(first_result(load_all(6000, 100, built)), 10)
        self.assertEqual(len(built), 6000)

    def test_container_types_differ(self):
        self.assertEqual(type(lazy_load(6000, 100)).__name__, "generator")
        self.assertEqual(type(load_all(6000, 100)).__name__, "list")

    def test_only_built_stays_small(self):
        values, built = only_built(6000, 100, 5)
        self.assertEqual([value for value, _ in values], [10, 11, 12, 13, 14])
        self.assertLess(built, 6000)
        self.assertLessEqual(built, 110)

    def test_counter_grows_slowly_for_lazy_but_not_eager(self):
        _, built_one = only_built(6000, 100, 1)
        _, built_five = only_built(6000, 100, 5)
        self.assertLess(built_one, 6000)
        self.assertLessEqual(built_five, built_one + 10)
        for _ in (1, 5):
            built = []
            load_all(6000, 100, built)
            self.assertEqual(len(built), 6000)


if __name__ == "__main__":
    unittest.main()
